<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Slot Management | C-Net Library</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial,sans-serif;background:#f3f6f8;color:#172033}.wrap{max-width:1450px;margin:28px auto;padding:0 18px}.top,.actions,.inline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;align-items:flex-start;margin-bottom:18px}.btn{border:0;border-radius:8px;padding:9px 12px;background:#102a43;color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.green{background:#0f766e}.red{background:#b91c1c}.light{background:#e2e8f0;color:#102a43}.card{background:#fff;border:1px solid #dfe7ed;border-radius:14px;padding:18px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.field label{display:block;font-size:12px;font-weight:800;color:#52677a;margin-bottom:5px}.field input,.field select{width:100%;padding:9px;border:1px solid #cbd5e1;border-radius:8px}.muted{color:#64748b;font-size:13px}.alert{padding:12px;border-radius:9px;margin-bottom:14px}.ok{background:#ecfdf5}.err{background:#fef2f2}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:1100px}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;vertical-align:top;font-size:13px}th{background:#f8fafc;color:#52677a}.inline input,.inline select{padding:7px;border:1px solid #cbd5e1;border-radius:7px}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#dcfce7;font-weight:800}.off{background:#fee2e2}.warn{background:#fff7ed;padding:8px;border-radius:8px;margin-top:7px}@media(max-width:750px){.grid{grid-template-columns:1fr}.top{flex-direction:column}}</style></head><body><div class="wrap"><div class="top"><div><h1 style="margin:0">Slot Management</h1><div class="muted">Create/edit study slots and attach monthly fee plans to each slot.</div></div><div class="actions"><a class="btn light" href="{{ route('admin.study-space.index') }}">Study Space</a><a class="btn" href="{{ route('admin.dashboard') }}">Dashboard</a></div></div>@if(session('success'))<div class="alert ok">{{ session('success') }}</div>@endif @if($errors->any())<div class="alert err"><strong>Please correct:</strong> {{ $errors->first() }}</div>@endif
<div class="card"><form method="GET" class="inline"><strong>Branch:</strong><select name="branch_id" onchange="this.form.submit()"><option value="">All Branches</option>@foreach($branches as $b)<option value="{{ $b->id }}" @selected($selectedBranchId==$b->id)>{{ $b->name }}</option>@endforeach</select></form></div>
<div class="card"><h2>Add New Slot</h2><form method="POST" action="{{ route('admin.study-space.slots.store') }}">@csrf<div class="grid"><div class="field"><label>Branch</label><select name="branch_id" required>@foreach($branches as $b)<option value="{{ $b->id }}" @selected($selectedBranchId==$b->id)>{{ $b->name }}</option>@endforeach</select></div><div class="field"><label>Slot Name</label><input name="name" placeholder="5 Hours Flexible" required></div><div class="field"><label>Duration</label><select name="duration_hours" required>@for($h=1;$h<=24;$h++)<option value="{{ $h }}">{{ $h }} {{ $h===1?'Hour':'Hours' }}</option>@endfor</select></div><div class="field"><label>Start Time (optional)</label><input type="time" name="start_time"></div><div class="field"><label>End Time (optional)</label><input type="time" name="end_time"></div><div class="field"><label>Type</label><div class="inline"><label><input type="checkbox" name="is_flexible" value="1"> Flexible / Free timing</label><label><input type="checkbox" name="is_24x7" value="1"> 24×7</label><label><input type="checkbox" name="status" value="1" checked> Active</label></div></div></div><p class="muted">Choose any duration from 1 to 24 hours. For a free slot, check Flexible and leave Start/End Time blank.</p><button class="btn green">Create Slot</button></form></div>

<div class="card"><h2>Add Monthly Plan</h2><div class="muted" style="margin-bottom:12px">After creating a slot, attach its monthly fee here.</div><form method="POST" action="{{ route('admin.study-space.plans.store') }}">@csrf<div class="grid"><div class="field"><label>Branch</label><select name="branch_id" required>@foreach($branches as $b)<option value="{{ $b->id }}" @selected($selectedBranchId==$b->id)>{{ $b->name }}</option>@endforeach</select></div><div class="field"><label>Study Slot</label><select name="study_slot_id" required><option value="">Select Slot</option>@foreach($slots as $slot)<option value="{{ $slot->id }}">{{ $slot->branch?->name }} · {{ $slot->name }} · {{ $slot->duration_hours }}h</option>@endforeach</select></div><div class="field"><label>Plan Name</label><input name="name" placeholder="5 Hours Monthly Plan" required></div><div class="field"><label>Monthly Fee (₹)</label><input type="number" step="0.01" min="0" name="monthly_fee" required></div><div class="field"><label>Validity Days</label><input type="number" min="1" name="validity_days" value="30" required></div><div class="field"><label>Admission Fee (optional)</label><input type="number" step="0.01" min="0" name="admission_fee"></div><div class="field"><label>Registration Fee (optional)</label><input type="number" step="0.01" min="0" name="registration_fee"></div><div class="field"><label>Security Deposit (optional)</label><input type="number" step="0.01" min="0" name="security_deposit"></div></div><input type="hidden" name="quarterly_fee"><input type="hidden" name="half_yearly_fee"><input type="hidden" name="yearly_fee"><input type="hidden" name="late_fee"><label class="inline" style="margin-top:10px"><input type="checkbox" name="status" value="1" checked> Active Plan</label><div style="margin-top:12px"><button class="btn green">Create Monthly Plan</button></div></form></div>

<div class="card"><h2>Existing Monthly Plans</h2><div class="tablewrap"><table><thead><tr><th>Branch</th><th>Plan</th><th>Slot</th><th>Monthly Fee</th><th>Validity</th><th>Status</th><th>Edit</th></tr></thead><tbody>@forelse($plans as $plan)<tr><td>{{ $plan->branch?->name }}</td><td><strong>{{ $plan->name }}</strong></td><td>{{ $plan->studySlot?->name }} · {{ $plan->studySlot?->duration_hours }}h</td><td>₹{{ number_format((float)$plan->monthly_fee,2) }}</td><td>{{ $plan->validity_days }} days</td><td><span class="badge {{ $plan->status?'':'off' }}">{{ $plan->status?'Active':'Disabled' }}</span></td><td><form method="POST" action="{{ route('admin.study-space.plans.update',$plan) }}">@csrf @method('PATCH')<div class="inline"><select name="study_slot_id">@foreach($slots->where('branch_id',$plan->branch_id) as $slot)<option value="{{ $slot->id }}" @selected($slot->id==$plan->study_slot_id)>{{ $slot->name }}</option>@endforeach</select><input name="name" value="{{ $plan->name }}" required><input type="number" step="0.01" min="0" name="monthly_fee" value="{{ $plan->monthly_fee }}" style="width:110px"><input type="number" min="1" name="validity_days" value="{{ $plan->validity_days }}" style="width:80px"><input type="hidden" name="quarterly_fee" value="{{ $plan->quarterly_fee }}"><input type="hidden" name="half_yearly_fee" value="{{ $plan->half_yearly_fee }}"><input type="hidden" name="yearly_fee" value="{{ $plan->yearly_fee }}"><input type="hidden" name="admission_fee" value="{{ $plan->admission_fee }}"><input type="hidden" name="registration_fee" value="{{ $plan->registration_fee }}"><input type="hidden" name="security_deposit" value="{{ $plan->security_deposit }}"><input type="hidden" name="late_fee" value="{{ $plan->late_fee }}"><label><input type="checkbox" name="status" value="1" @checked($plan->status)> Active</label><button class="btn green">Save Plan</button></div></form></td></tr>@empty<tr><td colspan="7">No monthly plans configured.</td></tr>@endforelse</tbody></table></div></div>

<div class="card"><h2>Existing Slots — Edit / Clear Timing / Delete</h2><div class="tablewrap"><table><thead><tr><th>Branch</th><th>Current Slot</th><th>Linked History</th><th>Edit Controls</th><th>Delete</th></tr></thead><tbody>@forelse($slots as $slot)<tr><td>{{ $slot->branch?->name }}</td><td><strong>{{ $slot->name }}</strong><div>{{ $slot->duration_hours }} Hours</div><div class="muted">{{ $slot->start_time?substr($slot->start_time,0,5):'No start time' }} — {{ $slot->end_time?substr($slot->end_time,0,5):'No end time' }}</div><span class="badge {{ $slot->status?'':'off' }}">{{ $slot->status?'Active':'Disabled' }}</span> · {{ $slot->is_24x7?'24×7':($slot->is_flexible?'Flexible':'Fixed') }}</td><td>Plans: {{ $slot->fee_plans_count }}<br>Memberships: {{ $slot->memberships_count }}<br>Allocations: {{ $slot->seat_allocations_count }}</td><td><form method="POST" action="{{ route('admin.study-space.slots.update',$slot) }}">@csrf @method('PATCH')<div class="inline"><input name="name" value="{{ $slot->name }}" required><select name="duration_hours">@for($h=1;$h<=24;$h++)<option value="{{ $h }}" @selected((int)$slot->duration_hours===$h)>{{ $h }}h</option>@endfor</select><input type="time" name="start_time" value="{{ $slot->start_time?substr($slot->start_time,0,5):'' }}"><input type="time" name="end_time" value="{{ $slot->end_time?substr($slot->end_time,0,5):'' }}"><label><input type="checkbox" name="is_flexible" value="1" @checked($slot->is_flexible)> Flexible</label><label><input type="checkbox" name="is_24x7" value="1" @checked($slot->is_24x7)> 24×7</label><label><input type="checkbox" name="clear_timing" value="1"> Clear Timing</label><label><input type="checkbox" name="status" value="1" @checked($slot->status)> Active</label><button class="btn green">Save Edit</button></div></form></td><td>@if($slot->fee_plans_count+$slot->memberships_count+$slot->seat_allocations_count===0)<form method="POST" action="{{ route('admin.study-space.slots.destroy',$slot) }}" onsubmit="return confirm('Delete this unused slot permanently?')">@csrf @method('DELETE')<button class="btn red">Delete Slot</button></form>@else<div class="warn">History exists. Permanent delete is blocked; uncheck Active and Save Edit to disable it safely.</div>@endif</td></tr>@empty<tr><td colspan="5">No slots configured.</td></tr>@endforelse</tbody></table></div></div></div></body></html>